//! Deterministic Rust crate generation from compiled definitions: the
//! reference processor's shape under a pinned writer profile, so the
//! same definition always generates byte-identical files.

mod catalog;
mod emit;
mod emit_compile;
mod manifest;
mod model;
mod render;

pub use emit::GeneratedTree;
pub use manifest::{MANIFEST_NAME, WriteError, check, write};

/// The exact first line of every generated Rust file: the one header
/// element an oracle comparison excludes, and nothing else.
pub const RUST_MARKER: &str = concat!(
    "// generated by kdlith ",
    env!("CARGO_PKG_VERSION"),
    "; do not edit."
);

/// The exact first line of the generated `Cargo.toml` and the output
/// manifest, the comment-spelled twin of [`RUST_MARKER`].
pub const COMMENT_MARKER: &str = concat!(
    "# generated by kdlith ",
    env!("CARGO_PKG_VERSION"),
    "; do not edit."
);

use std::path::Path;

use kdlith_diagnostic::{DiagnosticRecord, registry};
use kdlith_engine::{CheckScope, Definition, Extensions, ReadOptions};

/// Why a definition cannot generate a crate.
///
/// Matchable by kind, like every library error in this workspace: the
/// CLI layer renders the variant it receives; generation never fails by
/// string.
#[derive(Clone, Debug)]
#[non_exhaustive]
pub enum Error {
    /// The crate name is not a valid package name.
    InvalidCrateName { name: String },
    /// The definition declares no record, declaration, or contribution
    /// nodes, so a generated processor would have no items.
    NoItems,
    /// The definition declares no version; a generated processor pins
    /// the declarations it makes about what it reads.
    MissingVersion,
    /// Generation requires a fully checked definition; a local checking
    /// leaves names unresolved.
    IncompleteScope { scope: CheckScope },
    /// Two contributing documents collapse to the same module name.
    ModuleCollision {
        first: String,
        second: String,
        module: String,
    },
    /// A type expression with no Rust rendering this version defines.
    UnsupportedExpression { spelling: String },
    /// A declared type whose kind has no Rust rendering this version
    /// defines.
    UnsupportedTypeKind { name: String, kind: &'static str },
    /// A reading node's cases select more than one type, or a type no
    /// object declares; an item reads as one object type.
    UnsupportedCaseNode { node: String, types: Vec<String> },
    /// The item type `{ty}` has no compile glue; only the canonical
    /// definition vocabulary generates a definition loader.
    UnsupportedItem { name: String },
    /// A node bound without `type=` reads as a node-local type whose
    /// name a declared logical type already takes.
    LocalTypeCollision { node: String, ty: String },
    /// A name the definition admits has no spelling in the generated
    /// crate: it is no Rust identifier, it shadows a name a dialect
    /// crate spells unqualified, it takes another declared type's name,
    /// or it maps onto a sibling's spelling.
    UnspellableName {
        what: &'static str,
        owner: String,
        name: String,
        reason: &'static str,
    },
    /// Two reading nodes spell one `Item` variant for different items:
    /// `KDLITH-GEN004`.
    ItemVariantCollision {
        variant: String,
        node: String,
        other: String,
    },
    /// A seed document outside the repository's `pkg/` tree cannot be
    /// spelled as the pinned layout's relative include path.
    SeedOutsidePkg { path: String },
    /// The entry documents do not compile; the records say why.
    DefinitionRejected { records: Vec<DiagnosticRecord> },
}

impl std::fmt::Display for Error {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::InvalidCrateName { name } => {
                write!(f, "`{name}` is not a valid crate name")
            }
            Self::NoItems => {
                write!(
                    f,
                    "the definition declares no record, declaration, or contribution \
                     nodes; a processor has no items"
                )
            }
            Self::MissingVersion => {
                write!(
                    f,
                    "the definition declares no version; a generated processor pins one"
                )
            }
            Self::IncompleteScope { scope } => write!(
                f,
                "generation requires a completely checked definition, not scope={}",
                scope.name()
            ),
            Self::ModuleCollision {
                first,
                second,
                module,
            } => write!(
                f,
                "`{first}` and `{second}` both generate the module `{module}`"
            ),
            Self::UnsupportedExpression { spelling } => {
                write!(f, "the type expression `{spelling}` has no Rust rendering")
            }
            Self::UnsupportedTypeKind { name, kind } => write!(
                f,
                "the declared type `{name}` of kind `{kind}` has no Rust rendering"
            ),
            Self::UnsupportedCaseNode { node, types } => write!(
                f,
                "the node `{node}` dispatches its items to `{}`; a generated item \
                 reads as exactly one object type",
                types.join("`, `")
            ),
            Self::UnsupportedItem { name } => write!(
                f,
                "the item type `{name}` has no compile glue; only the canonical \
                 definition vocabulary generates a loader"
            ),
            Self::LocalTypeCollision { node, ty } => write!(
                f,
                "the node `{node}` declares no type=, and its local type `{ty}` \
                 collides with a declared type"
            ),
            Self::UnspellableName {
                what,
                owner,
                name,
                reason,
            } => write!(
                f,
                "the {what} `{name}` of `{owner}` has no Rust spelling in a generated crate: {reason}"
            ),
            Self::ItemVariantCollision {
                variant,
                node,
                other,
            } => f.write_str(&variant_collision(variant, node, other)),
            Self::SeedOutsidePkg { path } => write!(
                f,
                "the seed document `{path}` does not sit under the repository's \
                 `pkg/` tree, so the pinned layout cannot spell its include path"
            ),
            Self::DefinitionRejected { records } => {
                write!(
                    f,
                    "the definition does not compile: {} diagnostic(s)",
                    records.len()
                )
            }
        }
    }
}

impl std::error::Error for Error {}

const VARIANT_COLLISION: &str = "KDLITH-GEN004";

fn variant_collision(variant: &str, node: &str, other: &str) -> String {
    let template = registry::lookup(VARIANT_COLLISION).map_or("", |code| code.message_template);
    registry::render(template, &[other, node, variant])
}

/// How the generated manifest names the kdlith crates it depends on.
/// Every value is written verbatim: generation never inspects the
/// filesystem, so the manifest stays a pure function of its inputs.
#[derive(Clone, Debug, PartialEq, Eq)]
#[non_exhaustive]
pub enum Packaging {
    /// Path dependencies on the sibling crates (`../<crate>`), the
    /// in-checkout layout the oracles pin.
    Sibling,
    /// Path dependencies rooted at the given directory; each kdlith
    /// crate hangs off it by its directory name.
    Path(String),
    /// Registry dependencies at the given version requirement.
    Registry(String),
}

/// Generate the processor crate for `definition`, published as
/// `crate_name`, its manifest naming the kdlith crates by `packaging`:
/// deterministic bytes, nothing from the working tree. Write it with
/// [`write`] or compare it with [`check`].
pub fn generate(
    definition: &Definition,
    crate_name: &str,
    packaging: Packaging,
) -> Result<GeneratedTree, Error> {
    let mut tree = model::Emission::new(definition, crate_name, packaging)?.emit()?;
    tree.notes.clone_from(&definition.notes);
    Ok(tree)
}

/// Compile the dialect named by `entries` and generate its processor
/// crate, through the reference processor's loader: the entry documents
/// are read and bound before anything is generated.
pub fn generate_dialect(
    entries: &[&Path],
    extensions: &Extensions,
    crate_name: &str,
    packaging: Packaging,
) -> Result<GeneratedTree, Error> {
    let definition = kdlith_superproc::load_dialect(entries, extensions, CheckScope::Complete)
        .map_err(|records| Error::DefinitionRejected { records })?;
    generate(&definition, crate_name, packaging)
}

/// Compile the schema named by `entries`, under the canonical dialect,
/// and generate its data-document processor crate. The documents' own
/// import locations resolve under `options`.
pub fn generate_schema(
    entries: &[&Path],
    extensions: &Extensions,
    crate_name: &str,
    options: ReadOptions,
    packaging: Packaging,
) -> Result<GeneratedTree, Error> {
    let dialect = kdlith_superproc::seed(extensions)
        .map_err(|records| Error::DefinitionRejected { records })?;
    let scope = CheckScope::Complete;
    let definition =
        kdlith_superproc::load_schema_with(&dialect, entries, extensions, scope, options)
            .map_err(|records| Error::DefinitionRejected { records })?;
    generate(&definition, crate_name, packaging)
}
